INSERT INTO plant_timelines (plant_name, au_hardiness_zone, sow_to_seedling, seedling_to_harvest, harvest_window, growth_multiplier, watering_frequency, extra_care, key_activities)
VALUES
('Tomatoes', '8a', 21, 60, 45, 1.2, 4, ARRAY['Use frost protection when needed', 'Monitor night temperatures']::TEXT[], '[{"timing":21,"activity":"Fertilise","details":"Use balanced 5-5-5 organic fertilizer, apply 2 tablespoons per plant in a ring around the stem","category":"fertilizing"},{"timing":28,"activity":"Monitor for pests","details":"Check undersides of leaves for hornworms and aphids. Look for holes or spotted damage","category":"pest"},{"timing":35,"activity":"Install supports","details":"Place cage or 6-foot stakes 4 inches from stem base. Ensure stakes are sturdy and well-anchored","category":"planting"},{"timing":45,"activity":"Remove suckers and lower leaves","details":"Maintain plant health","category":"pruning"},{"timing":60,"activity":"Check first fruits for ripeness","details":"Monitor for maturity","category":"harvest"}]'::jsonb),
