('Broccoli', '8a', 14, 70, 14, 1, 4, ARRAY['Check for cabbage worms']::TEXT[], '[{"timing":0,"activity":"Sow seeds 1/2 inch deep","details":"Plant in rich, well-draining soil with pH 6.0-6.8. Space seeds 3 inches apart in rows 24 inches apart. Keep soil consistently moist until germination.","category":"planting"},{"timing":14,"activity":"Thin seedlings to 18 inches apart","details":"Select strongest seedlings with dark green leaves. Cut unwanted seedlings at soil level to avoid disturbing roots. Water deeply after thinning.","category":"planting"},{"timing":28,"activity":"Apply calcium-rich fertilizer","details":"Use balanced fertilizer with added calcium (5-5-5 + Ca). Apply 2 tablespoons per plant in a ring 4 inches from stem. Water thoroughly after application.","category":"fertilizing"},{"timing":35,"activity":"Check for cabbage white butterflies","details":"Inspect leaf undersides for yellow eggs and green caterpillars. Look for holes in leaves. Consider using row covers or organic BT spray if needed.","category":"pest"},{"timing":50,"activity":"Remove yellowing lower leaves","details":"Cut off any yellowing or damaged leaves at the stem. Improve air circulation. Keep area around plant clear of debris to prevent disease.","category":"pruning"},{"timing":65,"activity":"Monitor head development","details":"Check central head size - should be 4-7 inches wide. Look for tight, compact buds. Heads should be dark green with no yellowing or flowering.","category":"harvest"},{"timing":70,"activity":"Harvest before florets separate","details":"Cut stem 6 inches below head when buds are tight and compact. Harvest in morning for best flavor. Leave plant for potential side shoot development.","category":"harvest"}]'::jsonb),
