('Carrots', '8a', 14, 75, 21, 1.1, 4, ARRAY['Protect tops from frost']::TEXT[], '[{"timing":0,"activity":"Sow seeds 1/4 inch deep in loose soil","details":"Prepare soil 12 inches deep, removing rocks. Space seeds 1/2 inch apart in rows 12-18 inches apart. Soil must be loose and fine. Water gently with fine spray.","category":"planting"},{"timing":14,"activity":"Thin seedlings to 2 inches apart","details":"When seedlings are 2 inches tall, thin to 2 inches apart. Cut tops rather than pulling to avoid disturbing neighboring roots. Water after thinning.","category":"planting"},{"timing":21,"activity":"Apply light balanced fertilizer","details":"Use low-nitrogen fertilizer (5-10-10). Apply 1 tablespoon per 10 feet of row, 3 inches from plants. Too much nitrogen causes forking.","category":"fertilizing"},{"timing":30,"activity":"Monitor for carrot rust flies","details":"Look for wilting, reddish-purple leaves and tunnels in roots. Consider row covers. Remove affected plants immediately to prevent spread.","category":"pest"},{"timing":45,"activity":"Check root size by brushing away soil","details":"Gently brush soil from crown to check width. Ideal diameter is 1/2 to 3/4 inch at shoulder. Keep shoulders covered to prevent greening.","category":"harvest"},{"timing":60,"activity":"Begin harvesting baby carrots","details":"Harvest when roots are 1/2 inch in diameter. Loosen soil before pulling. Best harvested after morning dew has dried. Water before harvesting if soil is dry.","category":"harvest"},{"timing":75,"activity":"Harvest full-sized carrots","details":"Pull when tops of roots are 1-1.5 inches in diameter. Twist and pull gently while holding greens close to crown. Harvest before soil freezes.","category":"harvest"}]'::jsonb),
