('Cabbage', '8a', 14, 85, 14, 1, 4, ARRAY['Check for frost damage']::TEXT[], '[{"timing":0,"activity":"Sow seeds 1/2 inch deep","details":"Plant in fertile soil with pH 6.0-6.8. Space seeds 2 inches apart in rows 24 inches apart. Keep soil consistently moist. Ideal soil temperature 65-75°F.","category":"planting"},{"timing":14,"activity":"Thin to strongest seedling per spot","details":"Select seedlings with sturdy stems and dark green leaves. Space final plants 18-24 inches apart. Cut rather than pull unwanted seedlings. Water deeply after thinning.","category":"planting"},{"timing":28,"activity":"Apply nitrogen-rich fertilizer","details":"Use balanced organic fertilizer (10-5-5). Apply 2 tablespoons per plant in a ring 4 inches from stem. Water thoroughly. Avoid getting fertilizer on leaves.","category":"fertilizing"},{"timing":42,"activity":"Check for cabbage loopers","details":"Look for small green caterpillars and holes in leaves. Check leaf undersides daily. Remove by hand or use Bt spray. Monitor for cabbage white butterflies.","category":"pest"},{"timing":60,"activity":"Remove yellowing outer leaves","details":"Remove any yellowed, damaged, or diseased leaves at the base. Keep area around plant clear of debris. Ensure good air circulation to prevent disease.","category":"pruning"},{"timing":75,"activity":"Test head firmness","details":"Gently squeeze head - should be firm and compact. Check size (6-8 inches diameter typical). Look for tight, dense head formation. Monitor daily as harvest approaches.","category":"harvest"},{"timing":85,"activity":"Harvest when head is firm and full-sized","details":"Cut stem at base with sharp knife. Harvest early morning for best flavor. Leave a few outer leaves attached. Store in cool place. Check remaining plants for maturity.","category":"harvest"}]'::jsonb),
('Cabbage', '8b', 14, 85, 14, 1, 4, ARRAY['Check for frost damage']::TEXT[], '[{"timing":0,"activity":"Sow seeds 1/2 inch deep","details":"Plant in fertile soil with pH 6.0-6.8. Space seeds 2 inches apart in rows 24 inches apart. Keep soil consistently moist. Ideal soil temperature 65-75°F.","category":"planting"},{"timing":14,"activity":"Thin to strongest seedling per spot","details":"Select seedlings with sturdy stems and dark green leaves. Space final plants 18-24 inches apart. Cut rather than pull unwanted seedlings. Water deeply after thinning.","category":"planting"},{"timing":28,"activity":"Apply nitrogen-rich fertilizer","details":"Use balanced organic fertilizer (10-5-5). Apply 2 tablespoons per plant in a ring 4 inches from stem. Water thoroughly. Avoid getting fertilizer on leaves.","category":"fertilizing"},{"timing":42,"activity":"Check for cabbage loopers","details":"Look for small green caterpillars and holes in leaves. Check leaf undersides daily. Remove by hand or use Bt spray. Monitor for cabbage white butterflies.","category":"pest"},{"timing":60,"activity":"Remove yellowing outer leaves","details":"Remove any yellowed, damaged, or diseased leaves at the base. Keep area around plant clear of debris. Ensure good air circulation to prevent disease.","category":"pruning"},{"timing":75,"activity":"Test head firmness","details":"Gently squeeze head - should be firm and compact. Check size (6-8 inches diameter typical). Look for tight, dense head formation. Monitor daily as harvest approaches.","category":"harvest"},{"timing":85,"activity":"Harvest when head is firm and full-sized","details":"Cut stem at base with sharp knife. Harvest early morning for best flavor. Leave a few outer leaves attached. Store in cool place. Check remaining plants for maturity.","category":"harvest"}]'::jsonb),
