('Lettuce', '8a', 7, 45, 14, 1, 3, ARRAY['Protect from hard frost']::TEXT[], '[{"timing":0,"activity":"Sow seeds 1/8 inch deep","details":"Scatter seeds lightly on prepared soil, barely cover with fine soil. Space rows 12-18 inches apart. Keep soil consistently moist but not waterlogged.","category":"planting"},{"timing":7,"activity":"Thin seedlings to 6 inches apart","details":"Select strongest seedlings. For leaf lettuce, space 6 inches apart; for head lettuce, space 10-12 inches. Remove thinned seedlings at soil level to avoid disturbing roots.","category":"planting"},{"timing":14,"activity":"Fertilise","details":"Apply nitrogen-rich fertilizer (NPK 8-0-0) in a shallow furrow 3 inches from plant base. Use 1 tablespoon per 10 feet of row. Water in thoroughly.","category":"fertilizing"},{"timing":21,"activity":"Check for slugs and snails","details":"Inspect plants early morning or evening. Look for irregular holes in leaves and silvery slime trails. Remove debris where pests hide. Consider organic slug deterrents.","category":"pest"},{"timing":30,"activity":"Begin harvesting outer leaves","details":"Harvest outer leaves when 4-6 inches long. Cut leaves 1 inch above soil level to allow regrowth. Keep harvesting to prevent bolting.","category":"harvest"},{"timing":40,"activity":"Monitor for signs of bolting","details":"Watch for center stem elongation and bitter taste. Harvest entire plant if bolting begins. Note: Warm temperatures and long days trigger bolting.","category":"pest"}]'::jsonb),
